# Profile: HAProxy load balancer
# Thin wrapper that delegates to the profile_haproxy module.
class profile::loadbalancer::haproxy (
  Optional[String] $environment_name = fact('environment'),
) {
  class { 'profile_haproxy': }
}

class role::app_server {
  include profile::base::base
  include profile::loadbalancer::haproxy
  include profile::app::stack
  include profile::cache::redis
}

# Role: HAProxy load balancer node
# Composes base OS profile with HAProxy-specific profile.
class role::haproxy {
  if $facts['kernel'].downcase == 'linux' {
    Exec {
      path => '/usr/bin:/bin:/usr/sbin:/sbin',
    }
  }

  include ::profile::base::base
  contain ::profile::loadbalancer::haproxy

  Class['::profile::base::base'] -> Class['::profile::loadbalancer::haproxy']
}

